"""Build the approved visual component for the authenticated intelligence shell."""
from pathlib import Path
root=Path(__file__).resolve().parents[1]
src=(root/'intelligence/layout-preview/app.js').read_text(encoding='utf-8')
src=src[:src.index("window.addEventListener('hashchange',render)")]
src=src.replace("document.addEventListener(","listen(")
src=src.replace("本地快照", "数据快照").replace('本地预览不会启动这些任务，实时运行状态以线上任务记录为准。','采集进度与执行结果以同步记录为准。').replace('最近任务的只读快照。点击同步只演示本地反馈，不提交线上任务。','最近同步任务及执行状态。').replace('请更新本地数据快照后重新打开','请同步数据快照后重新打开')
src=src.replace('href="#evidence"','href="#library"')
src=src.replace("if(b.dataset.action)toast('本地预览：已演示操作反馈，未向线上发送同步请求。');","if(b.dataset.action)runAction(b);")
src=src.replace('<button data-action="sync" class="primary">同步当前渠道</button>','<button data-action="sync" class="primary">同步公众号与 X</button>')
src=src.replace('<button data-action="sync" class="primary">演示同步该渠道</button><p class="hint">订阅管理已并入全球信息感知；预览不修改线上账号。</p>', '<button data-action="sync" data-sync-id="${esc(s.id)}" data-sync-type="${esc(s.type)}" class="primary">同步该渠道</button>')
a=src.index('function addForm()');b=src.index('\n',a)
src=src[:a]+'''function addForm(){return `<form id="add-form" class="form-grid" style="margin-top:20px"><label>渠道类型<select id="new-type"><option value="mp">微信公众号</option><option value="rss">RSS</option></select></label><label>公众号文章链接或 RSS 地址<input id="new-source" type="url" required placeholder="https://"></label><label>RSS 名称（添加 RSS 时必填）<input id="new-name"></label><button type="submit" class="primary">添加订阅</button><p class="hint">公众号通过原始文章链接校验身份；RSS 保存名称和订阅地址。X 账号及批量发现请使用<a href="/wechat/subscriptions">订阅高级管理 ↗</a>。</p></form>`;}
'''+src[b:]
a=src.index("listen('submit'");src=src[:a]+'''
listen('submit',async e=>{if(e.target.id!=='add-form')return;e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const value=$('#new-source').value.trim();if($('#new-type').value==='rss'){const name=$('#new-name').value.trim();if(!name)throw Error('请填写 RSS 名称');await write('/api/rss/sources',{name,url:value});}else await write('/api/subscriptions/action',{action:'subscribe',articleUrl:value});toast('订阅已提交，正在更新渠道列表');await reloadSources();tab='channels';render();}catch(error){toast(error.message);}finally{button.disabled=false;}});
async function write(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:life.signal});const result=await r.json();if(!r.ok)throw Error(result.message||result.statusMessage||result.error||'操作未完成');return result;}
async function runAction(button){button.disabled=true;try{const type=button.dataset.syncType,id=button.dataset.syncId;if(button.dataset.action==='collection')await write('api/collection',{});else if(type==='rss'&&/^\d+$/.test(id))await write('/api/rss/sync',{sourceId:Number(id)});else if(type==='official'||String(id||'').startsWith('intel:'))await write('api/collection',{});else await write('/api/subscriptions/action',{action:button.dataset.action,id:id||undefined});toast('请求已提交，请在同步记录中查看执行状态');await reloadSources();if(tab==='jobs')$('#channel-content').innerHTML=channelContent();}catch(error){toast(error.message);}finally{button.disabled=false;}}
async function reloadSources(){invalidateSensingCache();const [subs,rss]=await Promise.all([get('/api/subscriptions'),get('/api/rss/sources')]);Object.assign(data,sourcePayload(subs,rss));}
data=payload;render();const statusTimer=selectedView==='sources'?setInterval(async()=>{if(globalThis.document.hidden)return;try{const state=await get('api/collection');if(!life.signal.aborted){data.collection=state;tickCollection();}}catch{}},30000):null;$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close();},{signal:life.signal});return ()=>{life.abort();clearInterval(statusTimer);clearTimeout(toastTimer);dispose();};
}
'''
prefix='''// Generated by scripts/build-sensing-ui.py from the approved visual design.
const responses=new Map(),pending=new Map();
export function invalidateSensingCache(){responses.clear();}
export async function get(url){const [path,query='']=url.split('?'),params=new URLSearchParams(query);for(const [key,value] of [...params])if(!value)params.delete(key);params.sort();url=path+(params.size?'?'+params:'');const cached=responses.get(url);if(cached&&Date.now()-cached.at<30000)return cached.value;if(pending.has(url))return pending.get(url);const task=(async()=>{const r=await fetch(url);const body=await r.json();if(!r.ok)throw Error(body.error||body.message||'数据读取失败');responses.set(url,{at:Date.now(),value:body});if(responses.size>24)responses.delete(responses.keys().next().value);return body;})();pending.set(url,task);try{return await task;}finally{pending.delete(url);}}
function sourcePayload(subs,rss){return {subscriptions:(subs.list||[]).map(s=>({...s,platform:s.payload?.platform||((s.id||'').startsWith('x:')?'x':'mp'),name:s.payload?.name||s.name||s.id,lastSync:s.last_sync,historyCount:s.legacy_count})),jobs:subs.jobs||[],rss};}
export async function loadSensingPayload(view,query,existing){const rawPromise=existing?Promise.resolve(existing):get('api/data'+query);const extraPromise=view==='sources'?Promise.all([get('/api/subscriptions'),get('/api/rss/sources')]).then(v=>sourcePayload(...v)):Promise.resolve({subscriptions:[],jobs:[],rss:{list:[]}});const catalogPromise=view==='library'?get('api/classification'+query).catch(e=>({ruleError:e.message})):Promise.resolve({});const [raw,extra,catalog]=await Promise.all([rawPromise,extraPromise,catalogPromise]);return {...extra,documents:catalog.documents||raw.documents,sources:raw.sources,topics:raw.topics,collection:raw.collection,processing:raw.processing,snapshotAt:raw.generatedAt,downloadedAt:raw.generatedAt,ruleError:catalog.ruleError||null,rulePublication:catalog.rulePublication};}
export function mountSensing(root,payload,selectedView){
const life=new AbortController(),document={querySelector:s=>root.querySelector(s),querySelectorAll:s=>root.querySelectorAll(s),body:root.querySelector('.sensing-shell')},location={hash:selectedView==='library'?'#evidence':'#sources'};
const listen=(type,callback)=>root.addEventListener(type,callback,{signal:life.signal});
'''
(root/'intelligence/public/sensing.js').write_text(prefix+src,encoding='utf-8')
css=(root/'intelligence/layout-preview/style.css').read_text(encoding='utf-8').replace(':root',':host').replace('body.light','.sensing-shell.light').replace('body{','.sensing-shell{')
css+='\n#app{padding:0;max-width:none}.sensing-shell{background:transparent}.intro{margin-top:10px}#page-title{display:block;color:var(--muted);margin-bottom:16px}\n'
(root/'intelligence/public/sensing.css').write_text(css,encoding='utf-8')

